1	import type {
2		GameHistoryListResult,
3		GameHistoryRepository,
4	} from "../../domain/game/ports/GameHistoryRepository";
5	import type { GameItemSelectionService } from "../../domain/game/services/GameItemSelectionService";
6	import type {
7		GameHistoryEntry,
8		GameItem,
9		GameRatingRecord,
10		GameRoundConfig,
11		GameRoundSummary,
12		RandomSource,
13	} from "../../domain/game/types";
14	import type { RecallRating } from "../../domain/shared/types";
15	
16	const ALL_RATINGS: readonly RecallRating[] = [1, 2, 3, 4, 5];
17	
18	/** Ratings counting as "recalled" toward accuracy — Good and Easy only. */
19	const CORRECT_RATINGS: ReadonlySet<RecallRating> = new Set([4, 5]);
20	
21	/**
22	 * The item's identity: a `symbolCharacter` for a symbol item, a `thaiWord`
23	 * for a word or tone item, a `sentenceId` for a sentence item — matches the
24	 * dedupe key each `GameItemSource`/`ToneGameItemSource` uses (see
25	 * CONTEXT.md, GameRatingRecord's `itemKey` doc comment). Prefixed with
26	 * `kind` because a mixed round draws from several pools at once, and a
27	 * symbol character can coincide with a vocab word's exact Thai spelling
28	 * (e.g. "ณ" is both a consonant and a one-character preposition) —
29	 * without the prefix, rating that symbol and that word as two separate
30	 * items in the same round would silently collapse into one record in
31	 * `recordRating`'s de-dupe below, undercounting the round. The same
32	 * reasoning is why a tone item's key is prefixed `tone:` rather than
33	 * `word:`, even though both hold a Thai word: a round can include a word's
34	 * `WordGameItem` and its `ToneGameItem` at once (task 2.2 wires
35	 * `includeTonePractice`), and those must rate as two separate items too.
36	 *
37	 * Exhaustive on `kind`: a new `GameItem` member must be a compile error
38	 * here rather than silently inheriting another kind's identity rule.
39	 */
40	function itemKeyOf(item: GameItem): string {
41		switch (item.kind) {
42			case "symbol":
43				return `symbol:${item.symbolCharacter}`;
44			case "word":
45				return `word:${item.thaiWord}`;
46			case "sentence":
47				return `sentence:${item.sentenceId}`;
48			case "tone":
49				return `tone:${item.thaiWord}`;
50			default: {
51				const _never: never = item;
52				throw new Error(`unhandled game item: ${JSON.stringify(_never)}`);
53			}
54		}
55	}
56	
57	/**
58	 * A round's ratings, as recorded so far. Every function here is a pure
59	 * function of the arguments it is given — no round-in-progress state ever
60	 * lives on this class, matching `ConductReviewUseCase`/`ReviewService`'s own
61	 * caller-holds-the-session convention (see CONTEXT.md). `AppContext.tsx`
62	 * wires this up as one long-lived singleton; a singleton holding mutable
63	 * per-round state would leak ratings between rounds and between mounts.
64	 *
65	 * No `CardRepository` is ever received here — only `GameItemSelectionService`
66	 * (which wraps it) and `GameHistoryRepository`. There is therefore no code
67	 * path through this use case that could ever call `CardRepository.save` or
68	 * `ReviewableCard.recordReview`: the SRS-isolation guarantee is structural,
69	 * not merely a rule nobody happens to break.
70	 */
71	export class PlayGameUseCase {
72		/**
73		 * Tracks which `GameRoundSummary` objects have already been persisted, so
74		 * that finishing/saving the same completed round twice (a duplicate
75		 * effect run, a duplicate button press) does not append a duplicate
76		 * history entry. Keyed by object identity, not content: two genuinely
77		 * distinct rounds that happen to produce an identical summary are still
78		 * two history entries. A `WeakSet` holds no strong reference, so it
79		 * never keeps a finished round's data alive past the caller's own use of
80		 * it — this is bookkeeping for `saveHistory`'s own idempotency, not
81		 * round-in-progress state.
82		 */
83		private readonly savedSummaries = new WeakSet<GameRoundSummary>();
84	
85		constructor(
86			private readonly selectionService: GameItemSelectionService,
87			private readonly historyRepository: GameHistoryRepository,
88		) {}
89	
90		startRound(config: GameRoundConfig, rng?: RandomSource): GameItem[] {
91			return this.selectionService.selectRound(config, rng);
92		}
93	
94		/**
95		 * Returns a new ratings array with `itemIndex`'s rating set to `rating`,
96		 * overwriting any prior rating for that same index rather than appending
97		 * a second record for it — recording twice for one item (a stray global
98		 * keypress landing on top of a click, see CONTEXT.md) must not double-
99		 * count that item in the finished summary.
100		 */
101		recordRating(
102			items: readonly GameItem[],
103			ratings: readonly GameRatingRecord[],
104			itemIndex: number,
105			rating: RecallRating,
106		): GameRatingRecord[] {
107			const item = items[itemIndex];
108			if (!item) return [...ratings];
109	
110			const itemKey = itemKeyOf(item);
111			const record: GameRatingRecord = {
112				itemKey,
113				kind: item.kind,
114				challengeDirection: item.challengeDirection,
115				rating,
116			};
117	
118			return [...ratings.filter((r) => r.itemKey !== itemKey), record];
119		}
120	
121		/**
